/**
 * Deterministic Synthetic Dataset Generator
 * ---------------------------------------------------------------------------
 * Generates:
 *  - 200 Customers
 *  - 30 Restaurants
 *  - 20 Delivery Partners
 *  - 600 Orders
 *  - Corresponding Ratings (~465+ completed order ratings)
 *
 * NOTE: All records generated by this module are 100% synthetic demonstration
 * data created for academic evaluation and software prototyping. They do not
 * represent real-world companies, individuals, or commercial statistics.
 */

export interface CustomerSeed {
  customer_id: number;
  full_name: string;
  email: string;
  phone: string;
  city: string;
  signup_date: string;
  customer_segment: 'New' | 'Regular' | 'VIP';
}

export interface RestaurantSeed {
  restaurant_id: number;
  restaurant_name: string;
  cuisine_type: string;
  city: string;
  area: string;
  commission_rate: number;
  avg_prep_time_min: number;
  is_active: number;
}

export interface DeliveryPartnerSeed {
  partner_id: number;
  partner_name: string;
  vehicle_type: 'Bike' | 'Scooter' | 'EV Scooter' | 'Bicycle';
  city: string;
  joining_date: string;
  is_active: number;
}

export interface OrderSeed {
  order_id: string;
  customer_id: number;
  restaurant_id: number;
  partner_id: number | null;
  order_datetime: string;
  city: string;
  order_amount: number;
  delivery_fee: number;
  discount_amount: number;
  total_amount: number;
  payment_method: 'UPI' | 'Credit Card' | 'Debit Card' | 'Wallet' | 'Cash on Delivery';
  order_status: 'Completed' | 'Cancelled';
  delivery_time_min: number | null;
  distance_km: number;
  cancellation_reason: string | null;
}

export interface RatingSeed {
  rating_id: number;
  order_id: string;
  customer_id: number;
  restaurant_id: number;
  partner_id: number | null;
  food_rating: number;
  delivery_rating: number;
  overall_rating: number;
  review_comment: string;
  rated_at: string;
}

// Seeded PRNG (Mulberry32) so synthetic dataset is 100% deterministic
function createRng(seed = 20261116) {
  let state = seed >>> 0;
  return () => {
    state += 0x6d2b79f5;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

