// 20 Delivery Partners
const PARTNER_NAMES = [
  'Rajesh Kumar', 'Suresh Babu', 'Manoj Tiwari', 'Deepak Yadav', 'Prakash Nair',
  'Imran Sheikh', 'Ramesh Gowda', 'Karthik Raja', 'Sanjay Chauhan', 'Amit Deshmukh',
  'Harish Verma', 'Vikas Pawar', 'Dinesh Reddy', 'Farhan Ali', 'Ganesh Shetty',
  'Mohan Das', 'Naveen Joshi', 'Vinod Pillai', 'Rakesh Solanki', 'Arvind Krishnan',
];

const PAYMENT_METHODS: Array<OrderSeed['payment_method']> = [
  'UPI', 'UPI', 'UPI', 'Credit Card', 'Debit Card', 'Wallet', 'Cash on Delivery',
];

const CANCELLATION_REASONS = [
  'Customer changed mind',
  'Restaurant high prep delay',
  'Delivery partner unavailable',
  'Incorrect delivery address',
  'Payment gateway timeout',
];

const POSITIVE_REVIEWS = [
  'Hot and fresh packaging, delivered right on time.',
  'Great portion size and authentic flavor.',
  'Smooth handoff by the delivery partner.',
  'Consistently good quality, worth ordering again.',
  'Prompt delivery even during dinner rush.',
];

const MIXED_REVIEWS = [
  'Food tasted good but arrived slightly delayed.',
  'Packaging was decent, spice level slightly high.',
  'Delivery took longer than estimated due to traffic.',
  'Portion could be slightly better for the price.',
];

function pad2(n: number): string {
  return n < 10 ? `0${n}` : `${n}`;
}

export interface SyntheticDataset {
  customers: CustomerSeed[];
  restaurants: RestaurantSeed[];
  deliveryPartners: DeliveryPartnerSeed[];
  orders: OrderSeed[];
  ratings: RatingSeed[];
}

export function generateSyntheticDataset(): SyntheticDataset {
  const rng = createRng(20261116);

  // 1. Generate 200 Customers across 6 cities
  const customers: CustomerSeed[] = [];
  for (let i = 1; i <= 200; i++) {
    const first = FIRST_NAMES[(i * 7 + Math.floor(rng() * 5)) % FIRST_NAMES.length];
    const last = LAST_NAMES[(i * 3 + Math.floor(rng() * 11)) % LAST_NAMES.length];
    const city = CITIES[(i - 1) % CITIES.length];
    const monthOffset = Math.floor(rng() * 14);
    const signupDate = new Date(Date.UTC(2025, 4 + monthOffset, 1 + Math.floor(rng() * 27)));
    const segmentRoll = rng();
    const customer_segment: CustomerSeed['customer_segment'] =
      segmentRoll > 0.78 ? 'VIP' : segmentRoll > 0.35 ? 'Regular' : 'New';

    customers.push({
      customer_id: i,
      full_name: `${first} ${last}`,
      email: `${first.toLowerCase()}.${last.toLowerCase()}${i}@example.test`,
      phone: `+91-98${pad2(10 + (i % 89))}${pad2(10 + ((i * 7) % 89))}${pad2(10 + ((i * 13) % 89))}`,
      city,
      signup_date: signupDate.toISOString().slice(0, 10),
      customer_segment,
    });
  }

  // 2. Generate 30 Restaurants
  const restaurants: RestaurantSeed[] = RESTAURANT_TEMPLATES.map((tpl, idx) => ({
    restaurant_id: idx + 1,
    restaurant_name: tpl.name,
    cuisine_type: tpl.cuisine,
    city: tpl.city,
    area: tpl.area,
    commission_rate: tpl.commission,
    avg_prep_time_min: tpl.prep,
    is_active: 1,
  }));

  // 3. Generate 20 Delivery Partners
  const vehicles: Array<DeliveryPartnerSeed['vehicle_type']> = ['Bike', 'Scooter', 'EV Scooter', 'Bicycle'];
  const deliveryPartners: DeliveryPartnerSeed[] = PARTNER_NAMES.map((name, idx) => {
    const city = CITIES[idx % CITIES.length];
    const joinMonth = Math.floor(rng() * 12);
    const joinDate = new Date(Date.UTC(2025, joinMonth, 2 + (idx % 25)));
    return {
      partner_id: idx + 1,
      partner_name: name,
      vehicle_type: vehicles[idx % vehicles.length],
      city,
      joining_date: joinDate.toISOString().slice(0, 10),
      is_active: 1,
    };
  });

  // Peak hour distribution weights (lunch 12-14, dinner 19-22)
  const hourBuckets = [
    8, 9, 10, 11,
    12, 12, 12, 13, 13, 13, 13, 14, 14,
    15, 16, 17, 18,
    19, 19, 19, 20, 20, 20, 20, 21, 21, 21, 22, 22,
    23, 0, 1,
  ];

  const customersByCity: Record<string, CustomerSeed[]> = {};
  const restaurantsByCity: Record<string, RestaurantSeed[]> = {};
  const partnersByCity: Record<string, DeliveryPartnerSeed[]> = {};

  for (const city of CITIES) {
    customersByCity[city] = customers.filter((c) => c.city === city);
    restaurantsByCity[city] = restaurants.filter((r) => r.city === city);
    partnersByCity[city] = deliveryPartners.filter((p) => p.city === city);
  }

  const cityWeighted: string[] = [
    'Bengaluru', 'Bengaluru', 'Bengaluru',
    'Mumbai', 'Mumbai', 'Mumbai',
    'Delhi', 'Delhi',
    'Hyderabad', 'Hyderabad',
    'Pune',
    'Chennai',
  ];

  // 4. Generate 600 Orders spanning Dec 2025 – Nov 2026 + Corresponding Ratings
  const orders: OrderSeed[] = [];
  const ratings: RatingSeed[] = [];
  let ratingCounter = 1;

  for (let idx = 1; idx <= 600; idx++) {
    const city = cityWeighted[Math.floor(rng() * cityWeighted.length)];
    const cityCustomers = customersByCity[city];
    const cityRestaurants = restaurantsByCity[city];
    const cityPartners = partnersByCity[city];

    // Bias 76% of orders toward first 65% of city customers so repeat-customer behavior is realistic
    const custIdx =
      rng() < 0.76
        ? Math.floor(rng() * Math.max(1, Math.floor(cityCustomers.length * 0.65)))
        : Math.floor(rng() * cityCustomers.length);
    const customer = cityCustomers[custIdx];

    const restaurant = cityRestaurants[Math.floor(rng() * cityRestaurants.length)];
    const partner = cityPartners[Math.floor(rng() * cityPartners.length)];
    const restMeta = RESTAURANT_TEMPLATES[restaurant.restaurant_id - 1];

    const monthProgress = Math.pow(rng(), 0.85);
    const monthIndex = Math.min(11, Math.floor(monthProgress * 12));
    const baseYear = monthIndex === 0 ? 2025 : 2026;
    const baseMonth = monthIndex === 0 ? 11 : monthIndex - 1;
    const maxDay = baseMonth === 1 ? 28 : 30;
    const day = 1 + Math.floor(rng() * maxDay);
    const hour = hourBuckets[Math.floor(rng() * hourBuckets.length)];
    const minute = Math.floor(rng() * 60);
    const second = Math.floor(rng() * 60);

    const orderDate = new Date(Date.UTC(baseYear, baseMonth, day, hour, minute, second));
    const orderDatetime = orderDate.toISOString().replace('T', ' ').slice(0, 19);

    const cuisineTicketBase: Record<string, number> = {
      'North Indian': 460,
      'South Indian': 280,
      Biryani: 420,
      Italian: 590,
      'Pan-Asian': 540,
      'Fast Food': 310,
      Continental: 650,
      Desserts: 260,
    };
    const baseAmt = cuisineTicketBase[restaurant.cuisine_type] ?? 400;
    const orderAmount = Number((baseAmt * (0.7 + rng() * 0.85)).toFixed(2));
    const distanceKm = Number((1.2 + rng() * 7.5).toFixed(2));
    const deliveryFee = Number((distanceKm > 5 ? 49 : distanceKm > 3 ? 35 : 25).toFixed(2));
    const discountAmount = rng() > 0.62 ? Number((orderAmount * (0.1 + rng() * 0.1)).toFixed(2)) : 0;
    const totalAmount = Number(Math.max(99, orderAmount + deliveryFee - discountAmount).toFixed(2));

    const paymentMethod = PAYMENT_METHODS[Math.floor(rng() * PAYMENT_METHODS.length)];
    const isCancelled = rng() < 0.095;
    const orderStatus: OrderSeed['order_status'] = isCancelled ? 'Cancelled' : 'Completed';

    const partnerSpeedOffset = (partner.partner_id % 5) - 2;
    const isPeak = (hour >= 12 && hour <= 14) || (hour >= 19 && hour <= 22);
    const rawDeliveryMin = Math.round(
      restaurant.avg_prep_time_min + distanceKm * 2.7 + (isPeak ? 6 : 0) + partnerSpeedOffset + (rng() * 10 - 3)
    );
    const deliveryTimeMin = isCancelled ? null : Math.max(14, Math.min(68, rawDeliveryMin));

    const orderId = `ORD-${baseYear}${pad2(baseMonth + 1)}-${String(idx).padStart(4, '0')}`;

    orders.push({
      order_id: orderId,
      customer_id: customer.customer_id,
      restaurant_id: restaurant.restaurant_id,
      partner_id: isCancelled && rng() < 0.4 ? null : partner.partner_id,
      order_datetime: orderDatetime,
      city,
      order_amount: orderAmount,
      delivery_fee: deliveryFee,
      discount_amount: discountAmount,
      total_amount: totalAmount,
      payment_method: paymentMethod,
      order_status: orderStatus,
      delivery_time_min: deliveryTimeMin,
      distance_km: distanceKm,
      cancellation_reason: isCancelled
        ? CANCELLATION_REASONS[Math.floor(rng() * CANCELLATION_REASONS.length)]
        : null,
    });

    // ~88% of completed orders receive a corresponding customer rating
    if (!isCancelled && rng() < 0.88) {
      const delayPenalty = deliveryTimeMin && deliveryTimeMin > 40 ? 0.8 : 0;
      const foodRaw = Math.min(5, Math.max(1.5, restMeta.qualityBias + (rng() * 0.9 - 0.45)));
      const deliveryRaw = Math.min(5, Math.max(1.5, 4.6 - delayPenalty + (rng() * 0.8 - 0.4)));
      const foodRating = Number(foodRaw.toFixed(1));
      const deliveryRating = Number(deliveryRaw.toFixed(1));
      const overallRating = Number((foodRating * 0.6 + deliveryRating * 0.4).toFixed(1));

      const ratedDate = new Date(orderDate.getTime() + (deliveryTimeMin ?? 30) * 60000 + 1800000);
      const commentPool = overallRating >= 4.0 ? POSITIVE_REVIEWS : MIXED_REVIEWS;

      ratings.push({
        rating_id: ratingCounter++,
        order_id: orderId,
        customer_id: customer.customer_id,
        restaurant_id: restaurant.restaurant_id,
        partner_id: partner.partner_id,
        food_rating: foodRating,
        delivery_rating: deliveryRating,
        overall_rating: overallRating,
        review_comment: commentPool[Math.floor(rng() * commentPool.length)],
        rated_at: ratedDate.toISOString().replace('T', ' ').slice(0, 19),
      });
    }
  }

  return {
    customers,
    restaurants,
    deliveryPartners,
    orders,
    ratings,
  };
}
